<?php
namespace App\Http\Controllers;
use App\Models\{Product,Sale,SaleItem,Contact,Payment};
use App\Services\InventoryService;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
class PosController extends Controller
{
 public function index(){return view('pos.index',['products'=>Product::with(['baseUnit','stock'])->where('is_active',1)->orderBy('name')->get(),'customers'=>Contact::whereIn('type',['customer','both'])->where('is_active',1)->orderBy('name')->get(),'businessUnits'=>\App\Models\BusinessUnit::where('is_active',1)->get()]);}
 public function store(Request $r,InventoryService $inventory){$d=$r->validate(['customer_id'=>'nullable|exists:contacts,id','business_unit_id'=>'nullable|exists:business_units,id','discount'=>'nullable|numeric|min:0','paid'=>'required|numeric|min:0','payment_method'=>'required|string|max:40','notes'=>'nullable|string','items'=>'required|array|min:1','items.*.product_id'=>'required|exists:products,id','items.*.quantity'=>'required|numeric|gt:0','items.*.unit_price'=>'required|numeric|min:0']);
  $sale=DB::transaction(function()use($d,$inventory){$subtotal=collect($d['items'])->sum(function($i){$p=Product::findOrFail($i['product_id']);return (float)$i['quantity']*(float)$p->sale_price;});$discount=min((float)($d['discount']??0),$subtotal);$total=max(0,$subtotal-$discount);$paid=min((float)$d['paid'],$total);$sale=Sale::create(['invoice_no'=>'INV-'.now()->format('ymd').'-'.Str::upper(Str::random(5)),'business_unit_id'=>$d['business_unit_id']??null,'customer_id'=>$d['customer_id']??null,'user_id'=>auth()->id(),'sold_at'=>now(),'subtotal'=>$subtotal,'discount'=>$discount,'tax'=>0,'total'=>$total,'paid'=>$paid,'due'=>$total-$paid,'payment_status'=>$paid<=0?'unpaid':($paid<$total?'partial':'paid'),'payment_method'=>$d['payment_method'],'notes'=>$d['notes']??null]);
   foreach($d['items'] as $item){$p=Product::with('baseUnit')->findOrFail($item['product_id']);$qty=(float)$item['quantity'];$price=(float)$p->sale_price;$cost=(float)($p->stock?->avg_cost ?? $p->purchase_price);SaleItem::create(['sale_id'=>$sale->id,'business_unit_id'=>$p->business_unit_id,'product_id'=>$p->id,'product_name'=>$p->name,'unit_name'=>$p->baseUnit->short_name,'quantity'=>$qty,'unit_price'=>$price,'unit_cost'=>$cost,'discount'=>0,'line_total'=>$qty*$price]);$inventory->move($p,null,$qty,'out','sale',$sale->id,$cost,'POS sale '.$sale->invoice_no);}
   if($sale->customer_id){DB::table('contact_transactions')->insert(['contact_id'=>$sale->customer_id,'reference_type'=>'sale','reference_id'=>$sale->id,'direction'=>'debit','amount'=>$total,'description'=>'Sale '.$sale->invoice_no,'transacted_at'=>now(),'user_id'=>auth()->id(),'created_at'=>now(),'updated_at'=>now()]);if($paid>0)DB::table('contact_transactions')->insert(['contact_id'=>$sale->customer_id,'reference_type'=>'sale_payment','reference_id'=>$sale->id,'direction'=>'credit','amount'=>$paid,'description'=>'Payment received '.$sale->invoice_no,'transacted_at'=>now(),'user_id'=>auth()->id(),'created_at'=>now(),'updated_at'=>now()]);}if($paid>0){Payment::create(['reference_type'=>'sale','reference_id'=>$sale->id,'contact_id'=>$sale->customer_id,'direction'=>'in','amount'=>$paid,'method'=>$d['payment_method'],'paid_at'=>now(),'user_id'=>auth()->id()]);DB::table('cash_transactions')->insert(['direction'=>'in','source_type'=>'sale','source_id'=>$sale->id,'amount'=>$paid,'description'=>'Sale '.$sale->invoice_no,'transacted_at'=>now(),'user_id'=>auth()->id(),'created_at'=>now(),'updated_at'=>now()]);}
   return $sale;});return redirect()->route('sales.show',$sale)->with('success','Sale completed successfully.');}
 public function show(Sale $sale){$sale->load(['items','customer']);return view('pos.invoice',compact('sale'));}
 public function sales(){return view('pos.sales',['sales'=>Sale::with('customer')->latest('sold_at')->paginate(25)]);}
}
